import { useEffect, useState, useCallback } from "react";
import { Link } from "react-router-dom";
import API from "../services/api";
import UnifiedNavbar from "../components/UnifiedNavbar";
import attendanceService from "../services/attendanceService";

/* ── Helpers ── */
function getInitials(name = "") {
  return name.trim().split(" ").map(w => w[0]).join("").slice(0, 2).toUpperCase();
}

const STATUS_CONFIG = {
  Present:  { pill: "sp-present",  barColor: "#16A34A", label: "Present"    },
  Absent:   { pill: "sp-absent",   barColor: "#DC2626", label: "Absent"     },
  Leave:    { pill: "sp-leave",    barColor: "#D97706", label: "On Leave"   },
  unmarked: { pill: "sp-unmarked", barColor: "var(--color-brand-primary)", label: "Not Marked" },
};

function StudentDashboard() {

  /* ── Pull logged-in student from localStorage ── */
  const storedUser  = localStorage.getItem("user");
  const authUser    = storedUser ? JSON.parse(storedUser) : {};
  const studentId   = authUser.id     || null;
  const authName    = authUser.name   || "Student";
  const authCourse  = authUser.course || "";

  /* ── State ── */
  const [profile,         setProfile]         = useState(null);
  const [todayAttendance, setTodayAttendance] = useState(null);
  const [attendanceStats, setAttendanceStats] = useState({ present: 0, absent: 0, leave: 0 });
  const [attendanceHistory, setAttendanceHistory] = useState([]);
  const [loading,         setLoading]         = useState(true);
  const [showHistory,     setShowHistory]     = useState(false);

  const today      = new Date().toISOString().split("T")[0];
  const todayLabel = new Date().toLocaleDateString("en-IN", {
    weekday: "long", year: "numeric", month: "long", day: "numeric",
  });
  const hour     = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";

  /* ── Fetch student profile + attendance ── */
  const fetchData = useCallback(async () => {
    if (!studentId) return;
    try {
      setLoading(true);

      /* 1. Student profile from /student/{id} */
      try {
        const profileRes = await API.get(`/student/${studentId}`);
        const data = profileRes.data;
        // Merge course from localStorage if API doesn't return it
        setProfile({
          ...data,
          course: data?.course || authCourse || "",
        });
      } catch {
        /* fallback to auth data */
        setProfile({ id: studentId, name: authName, email: authUser.email || "", course: authCourse });
      }

      /* 2. Today's attendance for this student */
      try {
        const todayRes = await attendanceService.getAttendanceRecord(studentId, today);
        setTodayAttendance(todayRes?.status || null);
      } catch {
        setTodayAttendance(null);
      }

      /* 3. Full attendance history for this student only */
      try {
        let records = [];

        try {
          /* First try: ask attendanceService with studentId param */
          const historyRes = await attendanceService.getAttendance({ studentId });
          const all = Array.isArray(historyRes) ? historyRes : [];

          /* Strict filter — String() comparison handles number/string mismatch */
          records = all.filter(r => String(r.studentId) === String(studentId));

          /* If service returned nothing after filter, try direct API call */
          if (records.length === 0 && all.length > 0) {
            records = all.filter(r => String(r.studentId) === String(studentId));
          }
        } catch {
          /* Second try: direct API call filtered by studentId */
          try {
            const directRes = await API.get(`/attendance?studentId=${studentId}`);
            const all = Array.isArray(directRes.data) ? directRes.data : [];
            records = all.filter(r => String(r.studentId) === String(studentId));
          } catch {
            records = [];
          }
        }

        setAttendanceHistory(records);
        setAttendanceStats({
          present: records.filter(a => a.status === "Present").length,
          absent:  records.filter(a => a.status === "Absent").length,
          leave:   records.filter(a => a.status === "Leave").length,
        });
      } catch {
        setAttendanceStats({ present: 0, absent: 0, leave: 0 });
      }

    } catch (error) {
      console.error("StudentDashboard fetchData error:", error);
    } finally {
      setLoading(false);
    }
  }, [studentId, today, authName, authUser.email]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  /* ── Derived values ── */
  const statusKey  = todayAttendance || "unmarked";
  const sc         = STATUS_CONFIG[statusKey] || STATUS_CONFIG.unmarked;
  const total      = attendanceStats.present + attendanceStats.absent + attendanceStats.leave;
  const pct        = total > 0 ? Math.round((attendanceStats.present / total) * 100) : 0;
  const displayName = profile?.name || authName;

  /* ── Sort history newest first ── */
  const sortedHistory = [...attendanceHistory].sort(
    (a, b) => new Date(b.date) - new Date(a.date)
  );

  return (
    <div className="dashboard">
      <UnifiedNavbar />

      <div className="main-content">

        {/* ── Welcome banner ── */}
        <div style={{
          background:      "var(--color-brand-gradient)",
          borderRadius:    "var(--radius-xl)",
          padding:         "var(--space-8) var(--space-10)",
          marginBottom:    "var(--space-8)",
          display:         "flex",
          alignItems:      "center",
          justifyContent:  "space-between",
          flexWrap:        "wrap",
          gap:             "var(--space-4)",
          position:        "relative",
          overflow:        "hidden",
        }}>
          <div style={{ position:"absolute", right:"-40px", top:"-40px", width:"180px", height:"180px", borderRadius:"50%", background:"rgba(255,255,255,0.08)", pointerEvents:"none" }} />
          <div style={{ position:"absolute", right:"60px", bottom:"-60px", width:"140px", height:"140px", borderRadius:"50%", background:"rgba(255,255,255,0.06)", pointerEvents:"none" }} />

          {/* Left — greeting + name */}
          <div style={{ position:"relative", zIndex:1, display:"flex", alignItems:"center", gap:"var(--space-4)" }}>
            {/* Avatar */}
            <div style={{
              width:           "56px",
              height:          "56px",
              borderRadius:    "var(--radius-full)",
              background:      "rgba(255,255,255,0.2)",
              border:          "2px solid rgba(255,255,255,0.4)",
              display:         "flex",
              alignItems:      "center",
              justifyContent:  "center",
              fontSize:        "var(--text-xl)",
              fontWeight:      "var(--font-bold)",
              color:           "white",
              flexShrink:      0,
            }}>
              {loading ? "…" : getInitials(displayName)}
            </div>
            <div>
              <div style={{ fontSize:"var(--text-sm)", color:"rgba(255,255,255,0.8)", fontWeight:"var(--font-medium)", marginBottom:"var(--space-1)" }}>
                {greeting} 👋
              </div>
              <div style={{ fontSize:"var(--text-2xl)", fontFamily:"var(--font-display)", fontWeight:"var(--font-bold)", color:"white", letterSpacing:"-0.02em", lineHeight:"var(--leading-tight)" }}>
                {loading ? "Loading…" : displayName}
              </div>
              <div style={{ fontSize:"var(--text-xs)", color:"rgba(255,255,255,0.65)", marginTop:"var(--space-1)" }}>
                {profile?.course && `${profile.course}  •  `}{!profile?.course && authCourse && `${authCourse}  •  `}{todayLabel}
              </div>
            </div>
          </div>

          {/* Right — today's status badge */}
          <div style={{
            background:      "rgba(255,255,255,0.15)",
            backdropFilter:  "blur(8px)",
            border:          "1px solid rgba(255,255,255,0.25)",
            borderRadius:    "var(--radius-lg)",
            padding:         "var(--space-4) var(--space-6)",
            textAlign:       "center",
            position:        "relative",
            zIndex:          1,
          }}>
            <div style={{ fontSize:"var(--text-xs)", color:"rgba(255,255,255,0.7)", fontWeight:"var(--font-semibold)", textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:"var(--space-2)" }}>
              Today's status
            </div>
            <div style={{ fontSize:"var(--text-lg)", color:"white", fontWeight:"var(--font-bold)" }}>
              {loading ? "…" : sc.label}
            </div>
          </div>
        </div>

        {/* ── Profile detail card ── */}
        <div style={{
          background:    "var(--color-surface)",
          border:        "1px solid var(--color-border)",
          borderRadius:  "var(--radius-lg)",
          padding:       "var(--space-6)",
          marginBottom:  "var(--space-6)",
          boxShadow:     "var(--shadow-xs)",
          display:       "flex",
          flexWrap:      "wrap",
          gap:           "var(--space-8)",
          alignItems:    "center",
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:"var(--space-4)" }}>
            <div style={{
              width:           "52px",
              height:          "52px",
              borderRadius:    "var(--radius-full)",
              background:      "var(--color-info-light)",
              display:         "flex",
              alignItems:      "center",
              justifyContent:  "center",
              fontSize:        "var(--text-lg)",
              fontWeight:      "var(--font-bold)",
              color:           "var(--color-info-dark)",
            }}>
              {loading ? "…" : getInitials(displayName)}
            </div>
            <div>
              <div style={{ fontSize:"var(--text-base)", fontWeight:"var(--font-bold)", color:"var(--color-text-primary)", letterSpacing:"-0.01em" }}>
                {loading ? "—" : displayName}
              </div>
              <div style={{ fontSize:"var(--text-xs)", color:"var(--color-text-tertiary)", marginTop:"2px" }}>
                Student
              </div>
            </div>
          </div>

          {[
            { label: "Student ID", value: profile?.id                                      || studentId   },
            { label: "Email",      value: profile?.email                                   || authUser.email || "—" },
            { label: "Course",     value: profile?.course || authCourse                    || "—"          },
          ].map((item) => (
            <div key={item.label}>
              <div style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", color:"var(--color-text-tertiary)", textTransform:"uppercase", letterSpacing:"0.06em", marginBottom:"var(--space-1)" }}>
                {item.label}
              </div>
              <div style={{ fontSize:"var(--text-sm)", fontWeight:"var(--font-medium)", color:"var(--color-text-primary)" }}>
                {loading ? "—" : item.value}
              </div>
            </div>
          ))}
        </div>

        {/* ── Attendance percentage card ── */}
        <div style={{
          background:    "var(--color-surface)",
          border:        "1px solid var(--color-border)",
          borderRadius:  "var(--radius-lg)",
          padding:       "var(--space-6) var(--space-8)",
          marginBottom:  "var(--space-8)",
          boxShadow:     "var(--shadow-xs)",
          display:       "flex",
          alignItems:    "center",
          gap:           "var(--space-8)",
          flexWrap:      "wrap",
        }}>
          {/* Big percentage number */}
          <div>
            <div style={{
              fontSize:      "3.5rem",
              fontWeight:    "var(--font-extrabold)",
              lineHeight:    1,
              letterSpacing: "-0.03em",
              color:         pct >= 75
                               ? "var(--color-success)"
                               : pct >= 50
                               ? "var(--color-warning)"
                               : "var(--color-danger)",
            }}>
              {loading ? "—" : `${pct}%`}
            </div>
            <div style={{
              fontSize:      "var(--text-xs)",
              fontWeight:    "var(--font-semibold)",
              color:         "var(--color-text-tertiary)",
              textTransform: "uppercase",
              letterSpacing: "0.08em",
              marginTop:     "var(--space-2)",
            }}>
              Attendance
            </div>
          </div>

          {/* Progress bar */}
          <div style={{ flex: 1, minWidth: "160px" }}>
            <div style={{
              height:       "10px",
              background:   "var(--color-neutral-200)",
              borderRadius: "var(--radius-full)",
              overflow:     "hidden",
            }}>
              <div style={{
                height:       "100%",
                width:        loading ? "0%" : `${pct}%`,
                borderRadius: "var(--radius-full)",
                background:   pct >= 75
                                ? "linear-gradient(90deg, #16A34A, #22C55E)"
                                : pct >= 50
                                ? "linear-gradient(90deg, #D97706, #FBBF24)"
                                : "linear-gradient(90deg, #DC2626, #EF4444)",
                transition:   "width 0.8s ease",
              }} />
            </div>
            <div style={{
              display:       "flex",
              justifyContent:"space-between",
              marginTop:     "var(--space-2)",
              fontSize:      "var(--text-xs)",
              color:         "var(--color-text-tertiary)",
            }}>
              <span>0%</span>
              <span style={{ color: pct >= 75 ? "var(--color-success)" : "var(--color-text-tertiary)", fontWeight:"var(--font-semibold)" }}>
                {pct >= 75 ? "✓ Good standing" : pct >= 50 ? "⚠ Needs improvement" : "✗ Low attendance"}
              </span>
              <span>100%</span>
            </div>
          </div>
        </div>

        {/* ── Action cards ── */}
        <div className="cards" style={{ marginBottom:"var(--space-8)" }}>

          {/* Today's attendance */}
          <div className="card">
            <div style={{ position:"absolute", top:0, left:0, right:0, height:"3px", background:sc.barColor, borderRadius:"var(--radius-lg) var(--radius-lg) 0 0" }} />
            <h3>Today's Attendance</h3>
            <div style={{ margin:"var(--space-3) 0 var(--space-4)" }}>
              <span className={`person-status-pill ${sc.pill}`} style={{ fontSize:"var(--text-sm)", padding:"var(--space-2) var(--space-4)" }}>
                {loading ? "Loading…" : sc.label}
              </span>
            </div>
            <Link to="/attendance" className="card-link">View Attendance →</Link>
          </div>

          {/* Monthly summary */}
          <div className="card">
            <h3>Monthly Summary</h3>
            <div className="attendance-mini-stats" style={{ margin:"var(--space-3) 0 var(--space-4)" }}>
              <span className="present">✓ {attendanceStats.present} Present</span>
              <span className="absent">✗ {attendanceStats.absent} Absent</span>
              <span className="leave">📋 {attendanceStats.leave} Leave</span>
            </div>
            <button
              onClick={() => setShowHistory(!showHistory)}
              className="card-link"
              style={{ background:"none", border:"none", cursor:"pointer", padding:0 }}
            >
              {showHistory ? "Hide History ↑" : "View History →"}
            </button>
          </div>

          {/* Today's menu */}
          <div className="card">
            <h3>Today's Menu</h3>
            <p style={{ color:"var(--color-text-secondary)", fontSize:"var(--text-sm)", margin:"var(--space-3) 0 var(--space-4)", lineHeight:"var(--leading-relaxed)" }}>
              Breakfast + Lunch served today
            </p>
            <Link to="/today-menu" className="card-link">View Menu →</Link>
          </div>

        </div>

        {/* ── Attendance history table ── */}
        {showHistory && (
          <div style={{
            background:    "var(--color-surface)",
            border:        "1px solid var(--color-border)",
            borderRadius:  "var(--radius-lg)",
            padding:       "var(--space-6)",
            boxShadow:     "var(--shadow-xs)",
            marginBottom:  "var(--space-8)",
            animation:     "slideInUp 0.3s ease",
          }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"var(--space-5)" }}>
              <h3 style={{ fontSize:"var(--text-lg)", fontWeight:"var(--font-semibold)", color:"var(--color-text-primary)" }}>
                Attendance History
                <span style={{ marginLeft:"var(--space-2)", fontSize:"var(--text-xs)", fontWeight:"var(--font-bold)", background:"var(--color-brand-gradient)", color:"white", padding:"2px 8px", borderRadius:"var(--radius-full)" }}>
                  {sortedHistory.length}
                </span>
              </h3>
              <button
                onClick={() => setShowHistory(false)}
                style={{ background:"none", border:"none", cursor:"pointer", color:"var(--color-text-tertiary)", fontSize:"var(--text-lg)", lineHeight:1, padding:"var(--space-1)" }}
              >
                ✕
              </button>
            </div>

            {sortedHistory.length === 0 ? (
              <p style={{ color:"var(--color-text-tertiary)", fontSize:"var(--text-sm)", textAlign:"center", padding:"var(--space-8) 0" }}>
                No attendance records found.
              </p>
            ) : (
              <div style={{ overflowX:"auto" }}>
                <table className="table">
                  <thead>
                    <tr>
                      <th style={{ textAlign:"left" }}>#</th>
                      <th style={{ textAlign:"left" }}>Date</th>
                      <th style={{ textAlign:"left" }}>Meal Type</th>
                      <th style={{ textAlign:"left" }}>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sortedHistory.map((record, idx) => (
                      <tr key={record.id || idx}>
                        <td style={{ color:"var(--color-text-tertiary)", fontSize:"var(--text-xs)" }}>
                          {idx + 1}
                        </td>
                        <td style={{ fontWeight:"var(--font-medium)" }}>
                          {record.date
                            ? new Date(record.date).toLocaleDateString("en-IN", { day:"2-digit", month:"short", year:"numeric" })
                            : "—"}
                        </td>
                        <td style={{ color:"var(--color-text-secondary)" }}>
                          {record.mealType || "Breakfast & Lunch"}
                        </td>
                        <td>
                          <span className={`person-status-pill ${STATUS_CONFIG[record.status]?.pill || "sp-unmarked"}`}>
                            {record.status || "Unmarked"}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

export default StudentDashboard;
